package core

import (
	"errors"
	"fmt"
	"strings"
)

// Typed IDs keep a task ID from being passed where a repo ID is expected.
// They are opaque strings generated by the database layer.
type (
	ProjectID   string
	RepoID      string
	WorktreeID  string
	TaskID      string
	ChangeSetID string
	ProposalID  string
	BuildID     string
	AuditID     string
	// DevServerID names one dev server (a target and a command), TerminalSessionID
	// one terminal session (docs/design/devservers.md, terminal.md).
	DevServerID       string
	TerminalSessionID string
	// RequestID is the idempotency key of one workspace-action submission
	// (docs/design/phase-6-actions.md). The browser generates it once per
	// submission; the server binds it to a digest of the request.
	RequestID string
	// NoticeID names one notification in the server history
	// (docs/design/phase-6-notifications.md).
	NoticeID string
	// OperationID names one new-repo initialization or publish operation
	// (docs/design/phase-6-newrepos.md). It is also the base of the
	// non-secret marker put in a created remote's description.
	OperationID string
)

// ErrInvalidID is returned for empty IDs or IDs with whitespace.
var ErrInvalidID = errors.New("invalid id")

func checkID(kind, id string) error {
	if id == "" || strings.ContainsAny(id, " \t\r\n/\\") {
		return fmt.Errorf("%s %q: %w", kind, id, ErrInvalidID)
	}
	return nil
}

// Validate reports whether the ID is well formed.
func (id ProjectID) Validate() error { return checkID("project id", string(id)) }

// Validate reports whether the ID is well formed.
func (id RepoID) Validate() error { return checkID("repo id", string(id)) }

// Validate reports whether the ID is well formed.
func (id WorktreeID) Validate() error { return checkID("worktree id", string(id)) }

// Validate reports whether the ID is well formed.
func (id TaskID) Validate() error { return checkID("task id", string(id)) }

// Validate reports whether the ID is well formed.
func (id ChangeSetID) Validate() error { return checkID("change set id", string(id)) }

// Validate reports whether the ID is well formed.
func (id ProposalID) Validate() error { return checkID("proposal id", string(id)) }

// Validate reports whether the ID is well formed.
func (id BuildID) Validate() error { return checkID("build id", string(id)) }

// Validate reports whether the ID is well formed.
func (id AuditID) Validate() error { return checkID("audit id", string(id)) }

// Validate reports whether the ID is well formed.
func (id DevServerID) Validate() error { return checkID("dev server id", string(id)) }

// Validate reports whether the ID is well formed.
func (id TerminalSessionID) Validate() error { return checkID("terminal session id", string(id)) }

// Validate reports whether the ID is well formed.
func (id RequestID) Validate() error { return checkID("request id", string(id)) }

// Validate reports whether the ID is well formed.
func (id NoticeID) Validate() error { return checkID("notice id", string(id)) }

// Validate reports whether the ID is well formed.
func (id OperationID) Validate() error { return checkID("operation id", string(id)) }
